import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./HomePage.css";

function HomePage() {
  const navigate = useNavigate();
  const [bookingHistory, setBookingHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [notifications, setNotifications] = useState([]);
  const [showNotifications, setShowNotifications] = useState(false);

  const menuItems = [
    { name: "Home", route: "/home" },
    { name: "Profile", route: "/profile" },
    { name: "Settings", route: "/settings" },
    { name: "About", route: "/about" },
    { name: "Logout", route: "/" }
  ];

  useEffect(() => {
    const userId = localStorage.getItem("userId"); 

    // Fetch booking history
    axios.get(`/api/booking-history`)
      .then((res) => {
        const userHistory = res.data.filter(h => h.changedBy?.id == userId);
        setBookingHistory(userHistory);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching booking history:", err);
        setLoading(false);
      });

    // Fetch facilities to show notifications for new additions
    axios.get(`/facilities`)
      .then((res) => {
        const facilityNotifications = res.data.map(f => ({
          id: f.facilityId,
          message: `New facility added: ${f.facilityName} in ${f.city}`,
          date: f.createdDate
        }));
        setNotifications(prev => [...prev, ...facilityNotifications]);
      })
      .catch(err => console.error("Error fetching facilities:", err));

    // Add 3-day reminders
    const lastReminder = localStorage.getItem("lastReminderDate");
    const today = new Date();
    if (!lastReminder || (today - new Date(lastReminder)) / (1000 * 60 * 60 * 24) >= 3) {
      const reminder = {
        id: "reminder-" + today.getTime(),
        message: "Parking slots are available! Come and book your slot.",
        date: today.toISOString()
      };
      setNotifications(prev => [reminder, ...prev]);
      localStorage.setItem("lastReminderDate", today.toISOString());
    }
  }, []);

  return (
    <div className="homepage-container">
      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-logo">Parking System</div>
        {menuItems.map((item, index) => (
          <button
            key={index}
            className="sidebar-btn"
            onClick={() => {
              if (item.name === "Logout") localStorage.removeItem("user");
              navigate(item.route);
            }}
          >
            {item.name}
          </button>
        ))}
      </aside>

      {/* Main Content */}
      <main className="main-content">
        <section className="hero-section">
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <h1>Welcome to Parking Slot System</h1>
            {/* Notification Icon */}
            <div style={{ position: "relative", cursor: "pointer" }} onClick={() => setShowNotifications(!showNotifications)}>
              <span role="img" aria-label="bell" style={{ fontSize: "24px" }}>🔔</span>
              {notifications.length > 0 && <span className="notification-count">{notifications.length}</span>}
              {showNotifications && (
                <div className="notification-dropdown">
                  {notifications.length === 0 ? <p>No new notifications</p> : (
                    notifications.map(n => (
                      <div key={n.id} className="notification-item">
                        {n.message}
                        <div className="notification-date">{new Date(n.date).toLocaleDateString()}</div>
                      </div>
                    ))
                  )}
                </div>
              )}
            </div>
          </div>
          <p>Manage your bookings, view facilities, and update your profile all in one place.</p>
          <button className="start-btn" onClick={() => navigate("/booking")}>
            Start Booking
          </button>
        </section>

        <section className="dashboard-cards">
          <div className="card">
            <h2>Booking History</h2>
            {loading ? (
              <p>Loading history...</p>
            ) : bookingHistory.length === 0 ? (
              <p>No bookings found.</p>
            ) : (
              <ul>
                {bookingHistory.slice(0, 5).map((history) => (
                  <li key={history.historyId}>
                    <strong>{history.booking?.slotName || "Slot"}:</strong> {history.statusChange} on {new Date(history.changeDate).toLocaleString()}
                  </li>
                ))}
              </ul>
            )}
            <button onClick={() => navigate("/booking-history")}>View Full History</button>
          </div>

          <div className="card">
            <h2>Facilities Details</h2>
            <p>Check available parking facilities, capacity, and other details.</p>
            <button onClick={() => navigate("/facilities")}>View Facilities</button>
          </div>

          <div className="card">
            <h2>Profile</h2>
            <p>Update your personal information and preferences.</p>
            <button onClick={() => navigate("/profile")}>Go to Profile</button>
          </div>
        </section>
      </main>
    </div>
  );
}

export default HomePage;
